arguments.command:
SDK_VERSION=$(./.dotnet/dotnet --version)
cat > global.json <<EOF
{
  "sdk": {
    "version": "$SDK_VERSION",
    "allowPrerelease": true,
    "rollForward": "latestFeature",
    "paths": [".dotnet", "\$host\$"]
  }
}
EOF
grep -qxF '.dotnet/' .gitignore 2>/dev/null || printf '.dotnet/\n' >> .gitignore
cat global.json

